package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"unicode/utf8"
)

// Route registry with permission requirements
var (
	routePermissions = map[string]string{
		"/api/users/list":    "read",
		"/api/users/delete":  "admin",
		"/api/config/export": "admin",
		"/api/config/view":   "read",
		"/api/health":        "none",
	}

	roleHierarchy = map[string]int{
		"admin":  3,
		"write":  2,
		"read":   1,
		"none":   0,
	}

	handlerRegistry = map[string]http.HandlerFunc{}
	registryMu      sync.RWMutex
	secretKey       = []byte("hmac-secret-key-2024")
)

func init() {
	registerHandler("/api/users/list", handleUsersList)
	registerHandler("/api/users/delete", handleUsersDelete)
	registerHandler("/api/config/export", handleConfigExport)
	registerHandler("/api/config/view", handleConfigView)
	registerHandler("/api/health", handleHealth)
}

func registerHandler(path string, handler http.HandlerFunc) {
	registryMu.Lock()
	defer registryMu.Unlock()
	handlerRegistry[path] = handler
}

// Token structure for authentication
type AuthToken struct {
	UserID   string `json:"user_id"`
	Role     string `json:"role"`
	IssuedAt int64  `json:"issued_at"`
}

// Verify HMAC signature of token
func verifyToken(tokenStr string) (*AuthToken, error) {
	parts := strings.SplitN(tokenStr, ".", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid token format")
	}

	payload, signature := parts[0], parts[1]

	mac := hmac.New(sha256.New, secretKey)
	mac.Write([]byte(payload))
	expectedSig := hex.EncodeToString(mac.Sum(nil))

	if !hmac.Equal([]byte(signature), []byte(expectedSig)) {
		return nil, fmt.Errorf("invalid signature")
	}

	decodedPayload, err := hex.DecodeString(payload)
	if err != nil {
		return nil, fmt.Errorf("invalid payload encoding")
	}

	var token AuthToken
	if err := json.Unmarshal(decodedPayload, &token); err != nil {
		return nil, fmt.Errorf("invalid token payload")
	}

	return &token, nil
}

// Normalize path: collapse slashes, resolve dots, lowercase
// This normalization is applied BEFORE permission lookup
func normalizePath(path string) string {
	if !utf8.ValidString(path) {
		return "/invalid"
	}

	// Collapse multiple slashes
	for strings.Contains(path, "//") {
		path = strings.ReplaceAll(path, "//", "/")
	}

	// Remove trailing slash
	if len(path) > 1 && path[len(path)-1] == '/' {
		path = path[:len(path)-1]
	}

	// Resolve path traversal
	path = strings.ReplaceAll(path, "/../", "/")
	path = strings.ReplaceAll(path, "/./", "/")

	return path
}

// Check if user role meets the required permission level
func checkPermission(userRole string, requiredPerm string) bool {
	userLevel, ok := roleHierarchy[userRole]
	if !ok {
		return false
	}

	requiredLevel, ok := roleHierarchy[requiredPerm]
	if !ok {
		return false
	}

	return userLevel >= requiredLevel
}

// resolveRoute finds the matching route for a normalized path
// Uses prefix matching with longest-match-wins semantics
func resolveRoute(normalizedPath string) (string, bool) {
	// Exact match first
	if _, exists := routePermissions[normalizedPath]; exists {
		return normalizedPath, true
	}

	// Prefix match - find longest matching prefix
	bestMatch := ""
	for route := range routePermissions {
		if strings.HasPrefix(normalizedPath, route) {
			if len(route) > len(bestMatch) {
				bestMatch = route
			}
		}
	}

	if bestMatch != "" {
		return bestMatch, true
	}

	return "", false
}

// Main router with auth middleware
func secureRouter(w http.ResponseWriter, r *http.Request) {
	// Step 1: Extract and verify token
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	token, err := verifyToken(strings.TrimPrefix(authHeader, "Bearer "))
	if err != nil {
		http.Error(w, "invalid token", http.StatusUnauthorized)
		return
	}

	// Step 2: Normalize the request path for permission lookup
	normPath := normalizePath(r.URL.Path)

	// Step 3: Resolve route and check permissions
	matchedRoute, found := resolveRoute(normPath)
	if !found {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	requiredPerm := routePermissions[matchedRoute]
	if !checkPermission(token.Role, requiredPerm) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}

	// Step 4: Dispatch to handler using the ORIGINAL request path
	// (after basic cleaning for safety)
	dispatchPath := cleanPathForDispatch(r.URL.Path)

	registryMu.RLock()
	handler, exists := handlerRegistry[dispatchPath]
	registryMu.RUnlock()

	if exists {
		handler(w, r)
	} else {
		http.Error(w, "handler not found", http.StatusNotFound)
	}
}

// cleanPathForDispatch does minimal cleaning on the original path
// for handler dispatch - preserves semantic meaning
func cleanPathForDispatch(path string) string {
	// Only collapse double slashes for dispatch
	for strings.Contains(path, "//") {
		path = strings.ReplaceAll(path, "//", "/")
	}
	if len(path) > 1 && path[len(path)-1] == '/' {
		path = path[:len(path)-1]
	}
	return path
}

// Handlers
func handleUsersList(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{"users": []string{"alice", "bob"}})
}

func handleUsersDelete(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{"status": "user deleted"})
}

func handleConfigExport(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{"config": "secret_db_password=hunter2", "api_keys": []string{"sk-12345"}})
}

func handleConfigView(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{"config": "sanitized_view"})
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{"status": "ok"})
}

func main() {
	http.HandleFunc("/", secureRouter)
	fmt.Println("Server starting on :8080")
	http.ListenAndServe(":8080", nil)
}
